create table public.decklists (id uuid primary key default gen_random_uuid(),tournament_id uuid not null references public.tournaments(id) on delete cascade,user_id uuid not null references public.profiles(user_id) on delete cascade,name text,submitted_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tournament_id,user_id));
create table public.decklist_cards (id uuid primary key default gen_random_uuid(),decklist_id uuid not null references public.decklists(id) on delete cascade,card_name text not null,scryfall_id uuid,oracle_id uuid,quantity smallint not null check(quantity between 1 and 99),section text not null default 'main' check(section in('main','sideboard')),created_at timestamptz not null default now());
create index decklists_tournament_idx on public.decklists(tournament_id,submitted_at);create index decklist_cards_decklist_idx on public.decklist_cards(decklist_id,section,card_name);alter table public.tournament_players add column decklist_id uuid unique references public.decklists(id) on delete restrict;
create or replace function public.enforce_tournament_registration() returns trigger language plpgsql security invoker set search_path=public as $$ declare t public.tournaments%rowtype; current_players integer; d public.decklists%rowtype; begin select * into t from public.tournaments where id=new.tournament_id for update; if not found then raise exception 'Tournament not found.'; end if; if t.status<>'registration' then raise exception 'Registration is closed.'; end if; if now()>t.registration_deadline then raise exception 'The registration deadline has passed.'; end if; if new.decklist_id is null then raise exception 'A decklist is required to register.'; end if; select * into d from public.decklists where id=new.decklist_id; if not found or d.tournament_id<>new.tournament_id or d.user_id<>new.user_id then raise exception 'Decklist must belong to this player and tournament.'; end if; if not exists(select 1 from public.decklist_cards where decklist_id=new.decklist_id and section='main') then raise exception 'Decklist must contain at least one main-deck card.'; end if; if t.max_players is not null then select count(*) into current_players from public.tournament_players where tournament_id=new.tournament_id and dropped_at is null; if current_players>=t.max_players then raise exception 'This tournament is full.'; end if; end if; return new; end; $$;
alter table public.decklists enable row level security;alter table public.decklist_cards enable row level security;
create policy decklists_read_private_then_public on public.decklists for select to anon,authenticated using(exists(select 1 from public.tournaments t where t.id=tournament_id and t.status='completed') or user_id=(select auth.uid()) or exists(select 1 from public.tournaments t where t.id=tournament_id and t.created_by=(select auth.uid())));
create policy decklists_insert_self on public.decklists for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.tournaments t where t.id=tournament_id and t.status='registration' and now()<=t.registration_deadline));
create policy decklists_update_self_before_start on public.decklists for update to authenticated using(user_id=(select auth.uid()) and exists(select 1 from public.tournaments t where t.id=tournament_id and t.status='registration')) with check(user_id=(select auth.uid()) and exists(select 1 from public.tournaments t where t.id=tournament_id and t.status='registration'));
create policy decklists_delete_self_before_start on public.decklists for delete to authenticated using(user_id=(select auth.uid()) and exists(select 1 from public.tournaments t where t.id=tournament_id and t.status='registration') and not exists(select 1 from public.tournament_players tp where tp.decklist_id=id));
create policy decklist_cards_read_private_then_public on public.decklist_cards for select to anon,authenticated using(exists(select 1 from public.decklists d join public.tournaments t on t.id=d.tournament_id where d.id=decklist_id and (t.status='completed' or d.user_id=(select auth.uid()) or t.created_by=(select auth.uid()))));
create policy decklist_cards_insert_owner on public.decklist_cards for insert to authenticated with check(exists(select 1 from public.decklists d join public.tournaments t on t.id=d.tournament_id where d.id=decklist_id and d.user_id=(select auth.uid()) and t.status='registration'));
create policy decklist_cards_update_owner on public.decklist_cards for update to authenticated using(exists(select 1 from public.decklists d join public.tournaments t on t.id=d.tournament_id where d.id=decklist_id and d.user_id=(select auth.uid()) and t.status='registration')) with check(exists(select 1 from public.decklists d join public.tournaments t on t.id=d.tournament_id where d.id=decklist_id and d.user_id=(select auth.uid()) and t.status='registration'));
create policy decklist_cards_delete_owner on public.decklist_cards for delete to authenticated using(exists(select 1 from public.decklists d join public.tournaments t on t.id=d.tournament_id where d.id=decklist_id and d.user_id=(select auth.uid()) and t.status='registration'));
grant select,insert,update,delete on public.decklists to authenticated;grant select on public.decklists to anon;grant select,insert,update,delete on public.decklist_cards to authenticated;grant select on public.decklist_cards to anon;
